select a.finprod_id finprodId, b.bookset_name finprodName, a.cdate busiDate, a.check_status status, a.inter_type interType from szt_interf_valuation a left join bok_bookset b on a.finprod_id=b.bookset_id where 1=1 and a.inter_type=#{type} and a.cdate =#{busiDate}
AND a.finprod_id in
#{booksetId}

select distinct PRODUCT_ID prodId from SYS_BATCH_GRP_PRDLINK WHERE 1 = 1
AND GROUP_SEQ IN
#{item}
